SELECT "u"."id" AS "user_id", "u"."first_name", "u"."last_name", COUNT(DISTINCT("p"."id")) AS "post_count", COUNT(DISTINCT("c"."id")) AS "comment_count", MAX("p"."created_at") AS "last_post_at" FROM "users" AS "u" INNER JOIN "posts" AS "p" ON ("p"."user_id" = "u"."id") LEFT JOIN "comments" AS "c" ON ("c"."post_id" = "p"."id") GROUP BY "u"."id" HAVING (COUNT(DISTINCT("p"."id")) >= 8) ORDER BY "post_count" DESC, "u"."id" ASC;
